1	//! Asking a checker for the component a session was just asked about (ADR 0022).
2	//!
3	//! The structural answer is always computed first and is a complete answer on its own. With a [`SemanticProvider`]
4	//! attached, [`SemanticHook::refine`] asks the checker for exactly that component, waits a bounded time, and merges
5	//! its props over the structural ones. A checker that is slower than the budget leaves the structural answer in
6	//! place, and its late answer is kept for the next request of the same, unedited component.
7	//!
8	//! There is one request in flight per component and version of its file: a caller that finds one waits on it instead
9	//! of asking again, and a caller someone is waiting for raises a background request it joins to interactive, so a
10	//! story asked while its own prefetch runs is answered when the prefetch is.
11	//!
12	//! An answer describes the component's props as the checker read them, which depends on every file the component
13	//! imports, not only its own. So the session drops every answer when any source file changes
14	//! ([`SemanticHook::invalidate`]), and an answer that was still on its way then is neither kept nor joined. The same
15	//! call tells the checker which files changed, since a warm one answers from what it read before (ADR 0026 S6).
16	
17	use std::hash::{Hash, Hasher};
18	use std::sync::atomic::{AtomicBool, Ordering};
19	use std::sync::{Arc, Condvar, Mutex, PoisonError};
20	use std::time::Duration;
21	
22	use rustc_hash::{FxHashMap, FxHasher};
23	
24	use super::ComponentAnswer;
25	use crate::pipeline::HtmlAttributeMode;
26	use crate::react_types::{checker_prop_used, react_props_wanted};
27	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
28	use crate::types::semantic::{
29	    Delivery, MergedProps, Priority, PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome, SemanticProp,
30	    SemanticProvider, SemanticTarget, SharedPriority, SourceChange, Superseding, drop_superseded, merge_semantic_props,
31	    unread_diagnostic,
32	};
33	
34	/// What one request of the checker made of a component: the component it found, if any, and what the checker said
35	/// about the request itself (an edit it was not told about, why a component kept its structural result). Both are the
36	/// answer, so a late answer, a joined one and every request the cache serves it to carry both.
37	#[derive(Clone, Default)]
38	struct Answered {
39	    component: Option<Arc<SemanticComponent>>,
40	    diagnostics: Vec<Diagnostic>,
41	}
42	
43	/// What became of one request to the checker, for every caller that waited on it.
44	#[derive(Clone)]
45	enum Settled {
46	    /// The checker answered: what is kept for the component, and what an unavailable checker says once per session.
47	    Answered { answered: Answered, once: Vec<Diagnostic> },
48	    /// The checker stopped without answering.
49	    Stopped,
50	}
51	
52	/// A request in flight. Every caller for the same component and version of its file waits on it instead of asking the
53	/// checker again.
54	struct Pending {
55	    /// What the checker answers it at; a caller someone is waiting for raises it on joining.
56	    priority: SharedPriority,
57	    settled: Mutex<Option<Settled>>,
58	    ready: Condvar,
59	}
60	
61	impl Pending {
62	    fn new(priority: Priority) -> Self {
63	        Self { priority: SharedPriority::new(priority), settled: Mutex::new(None), ready: Condvar::new() }
64	    }
65	
66	    fn settle(&self, settled: Settled) {
67	        *self.settled.lock().unwrap_or_else(PoisonError::into_inner) = Some(settled);
68	        self.ready.notify_all();
69	    }
70	
71	    /// What became of the request, if that is known within `wait`.
72	    fn wait(&self, wait: Duration) -> Option<Settled> {
73	        let settled = self.settled.lock().unwrap_or_else(PoisonError::into_inner);
74	        let (settled, _) = self
75	            .ready
76	            .wait_timeout_while(settled, wait, |settled| settled.is_none())
77	            .unwrap_or_else(PoisonError::into_inner);
78	        settled.clone()
79	    }
80	}
81	
82	/// What the checker said about one component at one version of its file, what it is still being asked, and the
83	/// generation they belong to.
84	#[derive(Default)]
85	struct AnswerCache {
86	    /// Raised by every [`SemanticHook::invalidate`]; an answer asked for under an earlier one is not stored.
87	    generation: u64,
88	    answers: FxHashMap<(String, u64), Answered>,
89	    /// Requests in flight under the current generation, by the same key as `answers`.
90	    pending: FxHashMap<(String, u64), Arc<Pending>>,
91	    /// The one copy of each prop the kept answers hold, for this generation.
92	    props: PropInterner,
93	}
94	
95	impl AnswerCache {
96	    /// `component` with each prop the one copy the kept answers share. A design system's components repeat the same
97	    /// props (Chakra's about a thousand style props each), and an answer kept with its own copies held about 6.7 MiB
98	    /// per Chakra component, so a session that answered a few hundred stories held gigabytes.
99	    fn shared(&self, component: Arc<SemanticComponent>) -> Arc<SemanticComponent> {
100	        let SemanticComponent { key, props, composes } = Arc::unwrap_or_clone(component);
101	        let props = props.into_iter().map(|prop| self.props.share_arc(prop)).collect();
102	        Arc::new(SemanticComponent { key, props, composes })
103	    }
104	}
105	
106	type Answers = Mutex<AnswerCache>;
107	
108	/// Where a request finds its answer.
109	enum Found {
110	    /// An answer kept from an earlier request.
111	    Cached(Answered),
112	    /// A request already in flight, to wait on.
113	    Joined(Arc<Pending>),
114	    /// Nothing: this caller asks, and others join it.
115	    Asking(Arc<Pending>),
116	}
117	
118	/// How long a request for a component the structural pass lists no props for waits for the checker, unless the session
119	/// says otherwise ([`SemanticHook::wait_empty`]): an empty answer is not worth showing early, and Chakra's `Button` takes
120	/// 0.4 to 0.8 s.
121	pub(crate) const DEFAULT_WAIT_EMPTY: Duration = Duration::from_secs(2);
122	
123	pub(crate) struct SemanticHook {
124	    provider: Arc<dyn SemanticProvider>,
125	    /// How long a request waits for the checker before it takes the structural answer.
126	    wait: Duration,
127	    /// How long it waits instead when the structural answer has no props; never less than `wait`.
128	    wait_empty: Duration,
129	    answers: Arc<Answers>,
130	    /// Set once the checker has been reported unavailable, so a session says so once, not per component.
131	    warned: AtomicBool,
132	}
133	
134	impl SemanticHook {
135	    pub(crate) fn new(provider: Arc<dyn SemanticProvider>, wait: Duration) -> Self {
136	        Self {
137	            provider,
138	            wait,
139	            wait_empty: DEFAULT_WAIT_EMPTY,
140	            answers: Arc::new(Mutex::new(AnswerCache::default())),
141	            warned: AtomicBool::new(false),
142	        }
143	    }
144	
145	    /// Sets how long a request for a component with no structural props waits for the checker. A wait at most `wait`
146	    /// gives such a component the same wait as every other.
147	    pub(crate) fn wait_empty(&mut self, wait_empty: Duration) {
148	        self.wait_empty = wait_empty;
149	    }
150	
151	    /// The wait for `answer`. Nobody waits for a background request: its answer is kept for the request that follows.
152	    /// Someone does for an interactive one, and longer when the structural pass found no props, since there is nothing
153	    /// to show before the checker answers. Any prop, even a degraded one, is an answer worth showing at the short wait.
154	    fn wait_for(&self, answer: &ComponentAnswer, priority: Priority) -> Duration {
155	        match (priority, answer.entry.props.is_empty()) {
156	            (Priority::Background, _) => Duration::ZERO,
157	            (Priority::Interactive, true) => self.wait_empty.max(self.wait),
158	            (Priority::Interactive, false) => self.wait,
159	        }
160	    }
161	
162	    /// Forget every answer, refuse the ones still being waited for, and tell the checker what changed: a source file
163	    /// changed, and the checker's props for any component can depend on it. The next request of each component asks
164	    /// the checker again, after it has been told, rather than joining a request asked before the change.
165	    pub(crate) fn invalidate(&self, change: SourceChange) {
166	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
167	        cache.generation += 1;
168	        cache.answers.clear();
169	        cache.pending.clear();
170	        cache.props = PropInterner::default();
171	        self.provider.changed(change);
172	    }
173	
174	    /// `answer` with the checker's props, when it has them within the wait `priority` gives it.
175	    pub(crate) fn refine(
176	        &self,
177	        mut answer: ComponentAnswer,
178	        mode: HtmlAttributeMode,
179	        priority: Priority,
180	    ) -> ComponentAnswer {
181	        let stamp = std::fs::read(&answer.entry.file_path).map(|bytes| {
182	            let mut hasher = FxHasher::default();
183	            bytes.hash(&mut hasher);
184	            hasher.finish()
185	        });
186	        let cache_key = stamp.ok().map(|stamp| (answer.key.clone(), stamp));
187	
188	        let (found, generation) = self.find(cache_key.as_ref(), priority);
189	        let pending = match found {
190	            Found::Cached(cached) => {
191	                self.apply(&mut answer, cached, mode);
192	                return answer;
193	            }
194	            Found::Joined(pending) => pending,
195	            Found::Asking(pending) => {
196	                self.ask(&answer, mode, &pending, cache_key, generation);
197	                pending
198	            }
199	        };
200	
201	        match pending.wait(self.wait_for(&answer, priority)) {
202	            Some(Settled::Answered { answered, once }) => {
203	                for diagnostic in once {
204	                    if !self.warned.swap(true, Ordering::Relaxed) {
205	                        answer.diagnostics.push(diagnostic);
206	                    }
207	                }
208	                self.apply(&mut answer, answered, mode);
209	            }
210	            Some(Settled::Stopped) => {
211	                let mut stopped = Diagnostic::new(
212	                    DiagnosticSeverity::Warning,
213	                    DiagnosticCode::SemanticBackend,
214	                    "the TypeScript checker stopped without answering; the structural props are used",
215	                );
216	                stopped.affects = vec![answer.key.clone()];
217	                answer.diagnostics.push(stopped);
218	            }
219	            None => {
220	                let mut pending = Diagnostic::new(
221	                    DiagnosticSeverity::Info,
222	                    DiagnosticCode::SemanticBackend,
223	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
224	                     replace them on the next request",
225	                );
226	                pending.affects = vec![answer.key.clone()];
227	                answer.diagnostics.push(pending);
228	            }
229	        }
230	        answer
231	    }
232	
233	    /// The kept answer for `key`, else the request in flight for it (raised when someone waits for this one), else a
234	    /// new request this caller makes, registered so the next caller joins it. One lock, so two callers never both ask.
235	    /// A file that could not be read has no key: its request is neither kept nor joined.
236	    fn find(&self, key: Option<&(String, u64)>, priority: Priority) -> (Found, u64) {
237	        let mut cache = self.answers.lock().unwrap_or_else(PoisonError::into_inner);
238	        let generation = cache.generation;
239	        if let Some(key) = key {
240	            if let Some(cached) = cache.answers.get(key) {
241	                return (Found::Cached(cached.clone()), generation);
242	            }
243	            if let Some(pending) = cache.pending.get(key) {
244	                match priority {
245	                    Priority::Interactive => pending.priority.raise(),
246	                    Priority::Background => {}
247	                }
248	                return (Found::Joined(pending.clone()), generation);
249	            }
250	        }
251	        let pending = Arc::new(Pending::new(priority));
252	        if let Some(key) = key {
253	            cache.pending.insert(key.clone(), pending.clone());
254	        }
255	        (Found::Asking(pending), generation)
256	    }
257	
258	    /// Asks the checker for `answer`'s component. Its outcome settles `pending` for every caller waiting on it and is
259	    /// kept for the next request, unless the cache was invalidated since `generation`. Called without the cache's lock,
260	    /// since a provider may deliver at once.
261	    fn ask(
262	        &self,
263	        answer: &ComponentAnswer,
264	        mode: HtmlAttributeMode,
265	        pending: &Arc<Pending>,
266	        key: Option<(String, u64)>,
267	        generation: u64,
268	    ) {
269	        let target = SemanticTarget {
270	            key: answer.key.clone(),
271	            file_path: answer.entry.file_path.clone(),
272	            display_name: answer.entry.display_name.clone(),
273	            exports: answer.entry.exports.clone(),
274	            described: answer
275	                .entry
276	                .props
277	                .values()
278	                .filter(|prop| !prop.description.is_empty())
279	                .map(|prop| prop.name.clone())
280	                .collect(),
281	            react_wanted: react_props_wanted(mode, &answer.entry.props),
282	        };
283	        let answers = self.answers.clone();
284	        let asked = answer.key.clone();
285	        let settling = pending.clone();
286	        let delivery = Delivery::new(move |outcome| {
287	            let mut settled = match outcome {
288	                Some(outcome) => {
289	                    let Read { answered, once } = read_outcome(&asked, outcome);
290	                    Settled::Answered { answered, once }
291	                }
292	                None => Settled::Stopped,
293	            };
294	            if let Some(key) = key {
295	                let mut cache = answers.lock().unwrap_or_else(PoisonError::into_inner);
296	                if cache.pending.get(&key).is_some_and(|registered| Arc::ptr_eq(registered, &settling)) {
297	                    cache.pending.remove(&key);
298	                }
299	                if let Settled::Answered { answered, .. } = &mut settled
300	                    && cache.generation == generation
301	                {
302	                    answered.component = answered.component.take().map(|component| cache.shared(component));
303	                    cache.answers.insert(key, answered.clone());
304	                }
305	            }
306	            settling.settle(settled);
307	        });
308	        self.provider.request_at(vec![target], pending.priority.clone(), delivery);
309	    }
310	
311	    /// Merges what the checker made of the component into `answer`: its props, if it found the component, then what it
312	    /// said about the request. The structural diagnostics its props supersede go first, so the checker's are never
313	    /// read as structural.
314	    fn apply(&self, answer: &mut ComponentAnswer, answered: Answered, mode: HtmlAttributeMode) {
315	        let Answered { component, diagnostics } = answered;
316	        let Some(component) = component else {
317	            answer.diagnostics.extend(diagnostics);
318	            return;
319	        };
320	        let structural = answer.entry.props.clone();
321	        let used: Vec<&Arc<SemanticProp>> = component
322	            .props
323	            .iter()
324	            .filter(|prop| checker_prop_used(mode, &prop.name, prop.react_declared, &structural))
325	            .collect();
326	        // A structural prop the checker did not return keeps its structural type, opaque or not, and a structural
327	        // diagnostic naming the component may be about it.
328	        let structural_left = structural
329	            .iter()
330	            .any(|(name, prop)| prop.prop_type.holds_opaque() && !used.iter().any(|answered| answered.name == *name));
331	        let MergedProps { kept, unread, diagnostics: syntax } = merge_semantic_props(
332	            &mut answer.entry,
333	            used.into_iter(),
