150	/// How long a request waits for the checker when `semanticWaitMs` is not set: about the first-story budget.
151	const DEFAULT_SEMANTIC_WAIT_MS: u32 = 150;
152	
153	/// An empty session for `options`: lazy when they say so, with a checker attached unless they turn it off.
154	fn new_session(options: JsExtractOptions) -> napi::Result<Arc<WatchSession>> {
155	    let lazy = options.lazy.unwrap_or(false);
156	    let semantic = options.checker.unwrap_or(true).then(|| {
157	        (
158	            options.tsconfig_path.clone(),
159	            options.src_dirs.first().cloned(),
160	            options.semantic_wait_ms.unwrap_or(DEFAULT_SEMANTIC_WAIT_MS),
161	            options.semantic_wait_empty_ms,
162	        )
163	    });
164	    let pipeline_options = PipelineOptions::try_from(options).map_err(napi::Error::from_reason)?;
165	    let session = match lazy {
166	        true => WatchSession::lazy(pipeline_options),
167	        false => WatchSession::new(pipeline_options),
168	    };
169	    let session = match semantic {
170	        Some((tsconfig, first_src, wait_ms, wait_empty_ms)) => {
171	            let checker = on_demand_checker(tsconfig, first_src);
172	            let session = session.with_semantic(checker, std::time::Duration::from_millis(u64::from(wait_ms)));
173	            match wait_empty_ms {
174	                Some(ms) => session.with_semantic_wait_empty(std::time::Duration::from_millis(u64::from(ms))),
175	                None => session,
176	            }
177	        }
178	        None => session,
179	    };
