  // Replacing a structural answer on screen (ADR 0022). The dev server says which component the browser shows; an
  // answer for it that went out with structural props is watched until the checker has answered every component in
  // it, and then the dev server has the docgen service ask again, which stores the checker's answer where the browser
  // reads it. Once per component and change to the files, and only while the browser still shows it.

  /** The component of the story the browser shows, once the dev server has said. */
  let open: string | undefined
  /** The components whose last answer went out with structural props, with the keys the checker had yet to answer. */
  const structural = new Map<string, string[]>()
  const watching = new Set<string>()
  /** The session revision each component's answer was last replaced at. */
  const replaced = new Map<string, number>()

  function answered(componentId: string, awaiting: string[]): void {
    if (awaiting.length === 0) {
      structural.delete(componentId)
      return
    }
    structural.set(componentId, awaiting)
    void watch(componentId)
  }

  async function watch(componentId: string): Promise<void> {
    const keys = structural.get(componentId)
    if (!keys || componentId !== open || watching.has(componentId)) return
    watching.add(componentId)
    try {
      const session = await getSession()
      const { revision } = session
      if (replaced.get(componentId) === revision) return
      const checked = await session.awaitChecker(keys, CHECKER_WAIT_MS)
      // Replaced only by the checker's answer to every component, for the answer still shown, on screen still.
      if (!checked.every(Boolean) || structural.get(componentId) !== keys || componentId !== open) return
      replaced.set(componentId, revision)
      structural.delete(componentId)
      link.post({ type: 'answered', componentId })
    } catch (error) {
      logger.debug(`[caliper-docgen] ${componentId}: ${(error as Error).message}; the next request asks the checker again`)
    } finally {
      watching.delete(componentId)
      // A later answer that also went out structural, while this one was watched, is watched in turn.
      if (structural.has(componentId) && structural.get(componentId) !== keys) void watch(componentId)
    }
  }

  // The prefetch beyond the opening story: the dev server names the stories after the one on screen, and their
  // components are resolved in the background, one story at a time, the checker's answers included. A newer list
  // replaces what is still queued.
  let queue: IndexEntry[] = []
  let prefetching = false

  async function drain(): Promise<void> {
    if (prefetching) return
    prefetching = true
    try {
      while (queue.length > 0) {
        const entry = queue.shift()!
        try {
          // oxlint-disable-next-line no-await-in-loop -- one story at a time, so a story someone opens waits behind one at most
          await prefetchStory(entry)
        } catch (error) {
          logger.debug(`[caliper-docgen] prefetch of ${entry.importPath} stopped: ${(error as Error).message}`)
        }
      }
    } finally {
      prefetching = false
    }
  }

  async function prefetchStory(entry: IndexEntry): Promise<void> {
    const importPath = getStoryImportPathFromEntry(entry)
    if (!importPath || !STORY_FILE_TEST_REGEXP.test(importPath)) return
    const { csf, storyPath } = await storyFile(entry, importPath)
    const session = await freshSession()
    const targets = [csf, ...extractDeclaredSubcomponents(csf).map(({ componentName }) => storyFor(csf, storyPath, componentName))]
    const keys = targets.flatMap((target) => {
      try {
        return [locate(session, target, storyPath).key]
      } catch {
        return []
      }
    })
    await session.prefetch(keys)
  }

  link.listen((message) => {
    // The browser asks for the component of every story it opens, so one it comes back to is answered by its own
    // request, from the checker's kept answer; only an answer that goes out while it is on screen is watched.
    if (message.type === 'open') {
      open = message.componentId
    } else {
      queue = [...message.entries]
      void drain()
    }
  })

  return (next) => async (input) => {
    const importPath = getStoryImportPathFromEntry(input.entry)
    if (!importPath || !STORY_FILE_TEST_REGEXP.test(importPath)) return next(input)
    const componentId = getComponentIdFromEntry(input.entry)
    const awaiting: string[] = []
    try {
      return await document(input.entry, importPath, awaiting)
    } catch (error) {
      logger.debug(`[caliper-docgen] ${importPath}: ${(error as Error).message}; asking the next docgen provider`)
      return next(input)
    } finally {
      answered(componentId, awaiting)
    }
  }
}

